import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';

// Helper to decompose InstancedMesh into a Group of Meshes
function decomposeInstancedMesh(instancedMesh) {
    const group = new THREE.Group();
    group.name = instancedMesh.name;
    group.position.copy(instancedMesh.position);
    group.rotation.copy(instancedMesh.rotation);
    group.scale.copy(instancedMesh.scale);

    const count = instancedMesh.count;
    const dummy = new THREE.Object3D();
    const geometry = instancedMesh.geometry;
    const material = instancedMesh.material;

    for (let i = 0; i < count; i++) {
        instancedMesh.getMatrixAt(i, dummy.matrix);
        dummy.matrix.decompose(dummy.position, dummy.rotation, dummy.scale);

        const mesh = new THREE.Mesh(geometry, material);
        mesh.position.copy(dummy.position);
        mesh.rotation.copy(dummy.rotation);
        mesh.scale.copy(dummy.scale);
        mesh.name = `${instancedMesh.name}_instance_${i}`;

        group.add(mesh);
    }
    return group;
}

// Create the scene
const root = createScene();

// Process InstancedMeshes
const instancesToReplace = [];
root.traverse(child => {
    if (child.isInstancedMesh) {
        instancesToReplace.push(child);
    }
});

instancesToReplace.forEach(im => {
    const group = decomposeInstancedMesh(im);
    const parent = im.parent;
    if (parent) {
        parent.add(group);
        parent.remove(im);
    }
});

